import torch
from easyvolcap.utils.base_utils import dotdict

def to_cuda(batch, device="cuda", ignore_list: bool = False) -> torch.Tensor:
    # Check if device is a string
    if not isinstance(device, str):
        raise ValueError("Device must be a string")

    # Check if device is a valid CUDA device
    try:
        torch.device(device)
    except ValueError:
        raise ValueError(f"Invalid CUDA device: {device}")

    # Check if CUDA device is available
    if device != "cpu":
        try:
            torch.cuda.is_available()
        except RuntimeError:
            raise RuntimeError(f"CUDA device {device} is not available")

    if isinstance(batch, (tuple, list)):
        # If batch is a tuple or list, recursively apply the to_cuda function to each element
        return type(batch)(to_cuda(element, device, ignore_list) for element in batch)
    elif isinstance(batch, dict):
        # If batch is a dictionary, recursively apply the to_cuda function to each value
        return {k: to_cuda(v, device, ignore_list) if k != "meta" else v for k, v in batch.items()}
    else:
        # If batch is not a tuple, list, dictionary, or PyTorch tensor, convert it to a PyTorch tensor and move it to the device
        return torch.as_tensor(batch).to(device, non_blocking=True)
