import json

class SQLiteMemoization:
    def __init__(self):
        import sqlite3
        self.connection = sqlite3.connect('cache.db')
        self.cursor = self.connection.cursor()
        self.cursor.execute("CREATE TABLE IF NOT EXISTS cache (hash TEXT PRIMARY KEY, result TEXT)")

    def _cache_result(self, arg_hash, result):
        cursor = self.connection.cursor()
        cursor.execute("SELECT result FROM cache WHERE hash = ?", (arg_hash,))
        stored_result = cursor.fetchone()
        if stored_result:
            return json.loads(stored_result[0])
        else:
            cursor.execute("INSERT INTO cache (hash, result) VALUES (?, ?)", (arg_hash, json.dumps(result)))
            self.connection.commit()
            return result
