class JPEGSerializer:
    def serialize(self, item: Image) -> Tuple[bytes, Optional[str]]:
        # Check if the image is already in JPEG format
        if item.mode in ['RGB', 'RGBA']:
            # If the image has a filename, read the file directly
            if item.filename:
                try:
                    with open(item.filename, 'rb') as f:
                        return f.read(), None
                except FileNotFoundError:
                    return None, f"File not found: {item.filename}"
            # If the image doesn't have a filename, convert it to JPEG format
            else:
                return item.tobytes(), None
        # If the image is not in RGB or RGBA format, raise an error
        else:
            raise TypeError("Unsupported image type")
